
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_xc_cc06_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_xc_cc06", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.634025086885627e+00, -2.466617631309434e+00, -3.236895539887810e+00, -3.443085321370093e+00, -3.414218786529585e+00, -3.232681119083193e+00, -2.925571279188385e+00, -2.510570717130975e+00, -2.017926697303365e+00, -1.504226757520960e+00, -1.056020457630535e+00, -7.786799032100938e-01, -6.323004933466140e-01, -5.230563415451127e-01, -3.833810919910785e-01, -2.455131346363612e-01, -1.284857601034885e-01, -4.708087182050956e-02, -1.084364215562867e-02, -1.309056417029486e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


